// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        if (caller == address(0)) caller = address(1);

        bool ok;
        string memory v;
        try c.version{gas: gasleft()}() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            ok = false;
            v = "";
        }

        assertTrue(ok && keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}
